//! Keeps the object support matrix in step with the code.
//!
//! `doc/blf-object-support.md` is generated by `tools/gen-support-matrix.py`;
//! this test fails when a type is added without a parser or a list row, so the
//! documentation cannot silently drift.

use std::collections::BTreeSet;
use std::fs;
use std::path::Path;

fn source(path: &str) -> String {
    fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join(path)).unwrap()
}

#[test]
fn every_documented_object_type_has_a_parser_and_a_row() {
    let matrix = fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../doc/blf-object-support.md"),
    )
    .unwrap();
    let mut types = 0;
    for line in matrix.lines() {
        let cells: Vec<&str> = line.split('|').map(str::trim).collect();
        // | id | type | bus | fields parsed | list row |
        if cells.len() < 7 || !cells[1].chars().all(|c| c.is_ascii_digit()) {
            continue;
        }
        types += 1;
        assert_eq!(cells[4], "yes", "{} has no parser", cells[2]);
        assert_eq!(cells[5], "yes", "{} has no list row", cells[2]);
    }
    assert!(types >= 120, "only {types} types listed");
}

/// Every enum variant between 1 and 133 must appear in the documentation.
#[test]
fn the_matrix_covers_every_enum_variant() {
    let matrix = fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../doc/blf-object-support.md"),
    )
    .unwrap();
    let listed: BTreeSet<u32> = matrix
        .lines()
        .filter_map(|line| {
            let cells: Vec<&str> = line.split('|').map(str::trim).collect();
            if cells.len() < 7 || !cells[1].chars().all(|c| c.is_ascii_digit()) {
                return None;
            }
            cells[1].parse().ok()
        })
        .collect();
    for raw in 1..=133u32 {
        let object_type = blf_core::ObjectType::from_raw(raw);
        let name = object_type.name();
        if name.starts_with("Reserved")
            || matches!(name, "Unknown" | "UnknownObject" | "LogContainer")
        {
            continue;
        }
        // Restore point containers are file structure, not message content.
        if matches!(object_type, blf_core::ObjectType::Unknown115) {
            continue;
        }
        assert!(
            listed.contains(&raw),
            "type {raw} ({name}) missing from the matrix"
        );
    }
}

#[test]
fn the_generator_and_the_parser_sources_agree() {
    // The generator keys on `object_type_name`; make sure that table covers
    // every id the enum knows, which is what the matrix relies on.
    let types = source("src/types.rs");
    for raw in 1..=133u32 {
        let name = blf_core::ObjectType::from_raw(raw).name();
        assert!(!name.is_empty(), "type {raw} has no name");
        assert!(
            !name.starts_with("Reserved") || name == "Reserved",
            "type {raw} has an unexpected reserved name {name}"
        );
    }
    assert!(types.contains("DistributedObjectChange"));
}
